class IsAuthorizedWorkspaceMember(permissions.BasePermission):
    def has_object_permission(self, request, view, obj):
        return request.user.workspaces.filter(id=obj.workspace_id).exists()

class WorkspaceDocumentUpdateView(generics.UpdateAPIView):
    queryset = WorkspaceDocument.objects.all()
    serializer_class = DocumentSerializer
    permission_classes = [permissions.IsAuthenticated, IsAuthorizedWorkspaceMember]
